66		}
67		identityProvider, err := s.Store.GetIdentityProvider(ctx, &store.FindIdentityProvider{
68			UID: &uid,
69		})
70		if err != nil {
71			return nil, status.Errorf(codes.Internal, "failed to get identity provider, error: %+v", err)
72		}
73		if identityProvider == nil {
74			return nil, status.Errorf(codes.NotFound, "identity provider not found")
75		}
