12	func (d *DB) UpsertReaction(ctx context.Context, upsert *store.Reaction) (*store.Reaction, error) {
13		fields := []string{"`creator_id`", "`content_id`", "`reaction_type`"}
14		placeholder := []string{"?", "?", "?"}
15		args := []interface{}{upsert.CreatorID, upsert.ContentID, upsert.ReactionType}
16		stmt := "INSERT INTO `reaction` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholder, ", ") + ")"
17		result, err := d.db.ExecContext(ctx, stmt, args...)
18		if err != nil {
19			return nil, err
20		}
21	
22		rawID, err := result.LastInsertId()
23		if err != nil {
24			return nil, err
25		}
26		id := int32(rawID)
27		reaction, err := d.GetReaction(ctx, &store.FindReaction{ID: &id})
28		if err != nil {
29			return nil, err
30		}
31		if reaction == nil {
32			return nil, errors.Errorf("failed to create reaction")
33		}
34		return reaction, nil
35	}
