37	func (d *DB) ListReactions(ctx context.Context, find *store.FindReaction) ([]*store.Reaction, error) {
38		where, args := []string{"1 = 1"}, []any{}
39	
40		if find.ID != nil {
41			where, args = append(where, "`id` = ?"), append(args, *find.ID)
42		}
43		if find.CreatorID != nil {
44			where, args = append(where, "`creator_id` = ?"), append(args, *find.CreatorID)
45		}
46		if find.ContentID != nil {
47			where, args = append(where, "`content_id` = ?"), append(args, *find.ContentID)
48		}
49		if len(find.ContentIDList) > 0 {
50			placeholders := make([]string, 0, len(find.ContentIDList))
51			for _, id := range find.ContentIDList {
52				placeholders = append(placeholders, "?")
53				args = append(args, id)
54			}
55			where = append(where, "`content_id` IN ("+strings.Join(placeholders, ",")+")")
56		}
57	
58		rows, err := d.db.QueryContext(ctx, `
59			SELECT
60				id,
61				UNIX_TIMESTAMP(created_ts) AS created_ts,
62				creator_id,
63				content_id,
64				reaction_type
65			FROM reaction
66			WHERE `+strings.Join(where, " AND ")+`
67			ORDER BY id ASC`,
68			args...,
69		)
70		if err != nil {
71			return nil, err
72		}
73		defer rows.Close()
74	
75		list := []*store.Reaction{}
76		for rows.Next() {
77			reaction := &store.Reaction{}
78			if err := rows.Scan(
79				&reaction.ID,
80				&reaction.CreatedTs,
81				&reaction.CreatorID,
82				&reaction.ContentID,
