108	func newDeploymentConfiguration() *deploymentConfiguration {
109		return &deploymentConfiguration{
110			identityProviders: map[string]*storepb.IdentityProvider{},
111			instanceSettings:  map[storepb.InstanceSettingKey]*storepb.InstanceSetting{},
112		}
113	}
114	
115	func isIdentityProviderDeploymentFilename(name string) bool {
116		// The original database-writing bootstrap accepted every filename with this
117		// prefix and suffix. Continue loading those names so an upgrade cannot
118		// silently fall back to stale credentials stored in the database.
119		return strings.HasPrefix(name, "memos-idp-") && strings.HasSuffix(name, ".json")
120	}
121	
122	func readDeploymentProtoJSON(path string, message proto.Message) error {
123		info, err := os.Stat(path)
124		if err != nil {
125			return errors.Wrap(err, "failed to inspect file")
126		}
127		if !info.Mode().IsRegular() {
128			return errors.New("file must resolve to a regular file")
129		}
130		file, err := os.Open(path)
131		if err != nil {
132			return errors.Wrap(err, "failed to open file")
133		}
134		defer file.Close()
135		info, err = file.Stat()
136		if err != nil {
137			return errors.Wrap(err, "failed to inspect file")
138		}
139		if !info.Mode().IsRegular() {
140			return errors.New("file must resolve to a regular file")
141		}
142		content, err := io.ReadAll(io.LimitReader(file, maxDeploymentConfigurationSize+1))
143		if err != nil {
144			return errors.Wrap(err, "failed to read file")
145		}
146		if len(content) > maxDeploymentConfigurationSize {
147			return errors.Errorf("file exceeds %d bytes", maxDeploymentConfigurationSize)
148		}
149		if err := (protojson.UnmarshalOptions{DiscardUnknown: false}).Unmarshal(content, message); err != nil {
150			if matches := protoJSONUnknownFieldMatcher.FindStringSubmatch(err.Error()); len(matches) == 2 {
151				return errors.Errorf("failed to decode protobuf JSON: unknown field %q", matches[1])
152			}
153			return errors.New("failed to decode protobuf JSON; verify field names, value types, and JSON syntax")
154		}
155		return nil
156	}
