158	func validateDeploymentIdentityProvider(provider *storepb.IdentityProvider) error {
159		if provider.Id != 0 {
160			return errors.New("id must be omitted")
161		}
162		if !base.UIDMatcher.MatchString(provider.Uid) {
163			return errors.New("uid is invalid")
164		}
165		if strings.TrimSpace(provider.Name) == "" {
166			return errors.New("name is required")
167		}
168		if provider.Type != storepb.IdentityProvider_OAUTH2 {
169			return errors.New("type must be OAUTH2")
170		}
171		if provider.IdentifierFilter != "" {
172			if _, err := regexp.Compile(provider.IdentifierFilter); err != nil {
173				return errors.Wrap(err, "identifierFilter must be a valid regular expression")
174			}
175		}
176		config := provider.Config.GetOauth2Config()
177		if config == nil {
178			return errors.New("config.oauth2Config is required")
179		}
180		required := []struct {
181			name  string
182			value string
183		}{
184			{name: "clientId", value: config.ClientId},
185			{name: "clientSecret", value: config.ClientSecret},
186			{name: "authUrl", value: config.AuthUrl},
187			{name: "tokenUrl", value: config.TokenUrl},
188			{name: "userInfoUrl", value: config.UserInfoUrl},
189		}
190		for _, field := range required {
191			if strings.TrimSpace(field.value) == "" {
192				return errors.Errorf("config.oauth2Config.%s is required", field.name)
193			}
194		}
195		for _, field := range []struct {
196			name  string
197			value string
198		}{
199			{name: "authUrl", value: config.AuthUrl},
200			{name: "tokenUrl", value: config.TokenUrl},
201			{name: "userInfoUrl", value: config.UserInfoUrl},
202		} {
203			parsed, err := url.ParseRequestURI(field.value)
204			if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
205				return errors.Errorf("config.oauth2Config.%s must be an absolute HTTP(S) URL", field.name)
206			}
207		}
208		if len(config.Scopes) == 0 {
209			return errors.New("config.oauth2Config.scopes is required")
210		}
211		for i, scope := range config.Scopes {
212			if strings.TrimSpace(scope) == "" {
213				return errors.Errorf("config.oauth2Config.scopes[%d] must not be empty", i)
214			}
215		}
216		if config.FieldMapping == nil || strings.TrimSpace(config.FieldMapping.Identifier) == "" {
217			return errors.New("config.oauth2Config.fieldMapping.identifier is required")
218		}
219		return nil
220	}
