382	func (s *Store) warnShadowedStoredIdentityProviders(ctx context.Context, config *deploymentConfiguration) error {
383		if len(config.identityProviders) == 0 {
384			return nil
385		}
386		providers, err := s.listStoredIdentityProviders(ctx, &FindIdentityProvider{})
387		if err != nil {
388			return errors.Wrap(err, "failed to inspect stored identity providers")
389		}
390		for _, provider := range providers {
391			if _, ok := config.identityProviders[provider.Uid]; ok {
392				slog.Warn("deployment identity provider shadows a stored provider; the stored configuration remains in the database", "uid", provider.Uid)
393			}
394		}
395		return nil
396	}
